current.assets.forEach(a => {
  const s = scoreAsset(a);
  if (a.needs_review || s === null) review.push(a);
  if (s !== null) scored.push({ a, s });
});

scored.forEach((x, i) => {
  const row = document.createElement("div");
  row.className = "row" + (x.a.asset_id === selectedId ? " selected" : "");
  row.onclick = () => selectAsset(x.a.asset_id);
  const task = taskState[x.a.asset_id];
  row.innerHTML = `
    <div class="rank">${i + 1}</div>
    <div class="bar">
      <span class="b-prox" style="width:${x.s.proximity * 100}%"></span>
      <span class="b-size" style="width:${x.s.size * 100}%"></span>
      <span class="b-val" style="width:${x.s.value * 100}%"></span>
    </div>
    <div class="info">
      <div class="name">${x.a.name} ${task ? `<span class="task-flag">${task.status}</span>` : ""}</div>
      <div class="sub">${x.a.asset_type} · ${Math.round(x.a.distance_to_fire_m)} m to fire</div>
    </div>
    <div class="score">${x.s.total.toFixed(2)}</div>`;
  list.appendChild(row);
});

all.forEach(({ a, total }) => {
  const color = total === null ? "#a8471f" : tierColor(total);
  const marker = L.circleMarker([a.latitude, a.longitude], {
    radius: total === null ? 8 : 6 + total * 6, color: "#fff", weight: 1.5, fillColor: color, fillOpacity: 0.95,
  }).addTo(markerLayer);
  marker.bindTooltip(`<b>${a.name}</b><br/>${total === null ? "needs review" : "priority " + total.toFixed(2)}`, { className: "fire-tip" });
  marker.on("click", () => selectAsset(a.asset_id));
});
